css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .grafico{width: 100%; max-width: 430px; height: auto; display: block; margin: 0 auto;}
.mz .preg-lista{display: flex; flex-direction: column; gap: 9px;}
.mz .preg-fila{font-size: 13.5px; line-height: 1.35;}
.mz .preg-hueco-grande{display: inline-block; min-width: 110px; border-bottom: 1.5px solid var(--bosque); height: 16px; vertical-align: middle; margin-left: 4px;}
.mz .op-lista{display: flex; flex-direction: column; gap: 11px;}
.mz .op-fila{display: flex; justify-content: space-between; align-items: center; gap: 12px; font-size: 13.5px; line-height: 1.3;}
.mz .op-cajas{display: inline-flex; align-items: center; gap: 6px; flex-shrink: 0;}
.mz .op-caja{display: inline-block; width: 170px; height: 30px; border: 1.5px dashed #000; border-radius: 6px;}
.mz .op-igual{font-family: sans-serif; font-weight: 800; font-size: 15px;}
.mz .op-res{display: inline-block; width: 52px; height: 30px; border: 1.5px solid var(--bosque); border-radius: 6px;}
.mz .orden-fila{display: flex; justify-content: center; align-items: flex-end; gap: 6px;}
.mz .orden-item{display: flex; flex-direction: column; align-items: center; gap: 3px;}
.mz .orden-num{font-family: sans-serif; font-size: 10px; font-weight: 800;}
.mz .orden-caja{width: 92px; height: 38px; border: 1.5px solid var(--bosque); border-radius: 6px;}
.mz .orden-flecha{font-family: sans-serif; font-weight: 800; font-size: 16px; padding-bottom: 10px;}
.mz .vf-lista{display: flex; flex-direction: column; gap: 9px;}
.mz .vf-fila{display: flex; justify-content: space-between; align-items: center; gap: 12px; font-size: 13px; line-height: 1.3;}
.mz .vf-pills{display: flex; gap: 8px; flex-shrink: 0;}
.mz .vf-pill{display: inline-flex; align-items: center; justify-content: center; width: 23px; height: 23px; border: 2px solid var(--bosque); border-radius: 50%; font-family: sans-serif; font-weight: 800; font-size: 12px;}
.mz .preg-fila{line-height: 1.725 !important;}
.mz .op-fila span,.mz .op-fila strong{line-height: 1.725 !important;}
